const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---------------------------------------------------------------------------
// Retinal fundus -- the back of the eye through a fundus camera. A warm
// choroidal orange field, the bright optic disc off to the nasal side with its
// cupped centre, and the retinal vasculature streaming out of it: superior and
// inferior arcades sweeping around the dark avascular macula, arteries thinner
// and brighter with a central light reflex, veins broader and darker. Blood
// pulses along every vessel on the cardiac cycle and the camera illumination
// pool drifts slowly across the retina. Fundus photo, fluorescein angiogram,
// red-free monochrome, or a schematic vessel map.
// ---------------------------------------------------------------------------
const sd = P.seed | 0;
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7) * 43758.5453; return s - Math.floor(s); };
function hh(ix, iy) { let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(sd + 7, 1442695041)) | 0; h = Math.imul(h ^ (h >>> 13), 1274126177) | 0; return ((h ^ (h >>> 16)) >>> 0) / 4294967295; }
function sstep(t) { return t * t * (3 - 2 * t); }
function vn(x, y) { const xi = Math.floor(x), yi = Math.floor(y), xf = sstep(x - xi), yf = sstep(y - yi); const a = hh(xi, yi), b = hh(xi + 1, yi), c = hh(xi, yi + 1), d = hh(xi + 1, yi + 1); return (a + (b - a) * xf) * (1 - yf) + (c + (d - c) * xf) * yf; }

const u = Math.min(width, height);
const style = P.style;
const cx = width * 0.5, cy = height * 0.5, R = u * 0.47;
// eye orientation: disc nasal (to one side), macula at centre
const side = (sd % 2 === 0) ? 1 : -1;
const disc = { x: cx + side * R * 0.42, y: cy - R * 0.04 };
const mac = { x: cx, y: cy + R * 0.02 };

// ---- cached base field (choroid + disc + macula + border), per size/seed/style ----
if (!S.base || S.bkey !== width + 'x' + height + style + sd) {
  S.bkey = width + 'x' + height + style + sd;
  const b = S.base = createGraphics(width, height); b.pixelDensity(1);
  b.loadPixels(); const bp = b.pixels;
  for (let j = 0; j < height; j++) for (let i = 0; i < width; i++) {
    const dx = i - cx, dy = j - cy, rr = Math.sqrt(dx * dx + dy * dy) / R;
    const o = 4 * (j * width + i);
    if (rr > 1.0) { bp[o] = 6; bp[o + 1] = 4; bp[o + 2] = 6; bp[o + 3] = 255; continue; }
    const chor = vn(i / u * 9, j / u * 9) * 0.5 + vn(i / u * 22 + 3, j / u * 22 - 2) * 0.3;
    const vig = 1 - 0.55 * Math.pow(rr, 2.4);
    const dd = Math.sqrt((i - disc.x) * (i - disc.x) + (j - disc.y) * (j - disc.y)) / (R * 0.16);
    const md = Math.sqrt((i - mac.x) * (i - mac.x) + (j - mac.y) * (j - mac.y)) / (R * 0.28);
    let r, gg, bl;
    if (style === 'fa') {                          // fluorescein: dark, faint choroid
      const base = 0.06 + chor * 0.06;
      const dg = Math.max(0, 1 - dd) * 0.5;        // disc mildly fluorescent
      r = base + dg * 0.6; gg = base + dg * 0.65; bl = base * 0.9 + dg * 0.4;
      r *= vig; gg *= vig; bl *= vig;
    } else if (style === 'redfree') {              // green channel monochrome
      const base = (0.34 + chor * 0.32) * vig;
      const disc2 = Math.max(0, 1 - dd) * 0.4;
      r = base * 0.15; gg = base + disc2; bl = base * 0.2;
    } else if (style === 'schematic') {
      r = 0.05; gg = 0.10; bl = 0.17;
    } else {                                        // photo: warm orange choroid
      const base = 0.42 + chor * 0.4;
      const macDark = 1 - Math.max(0, 1 - md) * 0.55;      // darker macula
      const discBright = Math.max(0, 1 - dd);
      const cup = Math.max(0, 0.55 - dd) * 1.4;
      r = (base * 1.0 * macDark + discBright * 0.55 + cup * 0.3) * vig;
      gg = (base * 0.5 * macDark + discBright * 0.5 + cup * 0.35) * vig;
      bl = (base * 0.22 * macDark + discBright * 0.42 + cup * 0.4) * vig;
      const h = P.hue / 360; r *= 1 + Math.cos(h * 6.28) * 0.06; bl *= 1 + Math.sin(h * 6.28) * 0.1;
    }
    bp[o] = Math.max(0, Math.min(255, r * 255));
    bp[o + 1] = Math.max(0, Math.min(255, gg * 255));
    bp[o + 2] = Math.max(0, Math.min(255, bl * 255));
    bp[o + 3] = 255;
  }
  b.updatePixels();
}

// ---- vessel tree structure, per size/seed ----
if (!S.tree || S.tkey !== width + 'x' + height + sd) {
  S.tkey = width + 'x' + height + sd;
  const segs = []; let idc = 0;
  // four arcade trunks leaving the disc
  const trunks = [
    { a: side > 0 ? -2.55 : -0.6, art: true, arc: -1 },   // superior-temporal
    { a: side > 0 ? 2.55 : 0.6, art: false, arc: 1 },     // inferior-temporal
    { a: side > 0 ? -1.9 : -1.25, art: false, arc: -0.3 },
    { a: side > 0 ? 1.9 : 1.25, art: true, arc: 0.3 }
  ];
  function grow(x, y, ang, w, dep, art, arc) {
    if (w < u * 0.0018 || dep > 9) return;
    const len = u * (0.05 + fr(idc * 1.3) * 0.05) * (1 + (9 - dep) * 0.08);
    // arcades curve around the macula
    const toMac = Math.atan2(mac.y - y, mac.x - x);
    let da = arc * 0.14 + Math.sin(idc * 2.1) * 0.12;
    const nx = x + Math.cos(ang) * len, ny = y + Math.sin(ang) * len;
    const midx = (x + nx) / 2 - Math.sin(ang) * len * da * 4;
    const midy = (y + ny) / 2 + Math.cos(ang) * len * da * 4;
    segs.push({ x, y, mx: midx, my: midy, nx, ny, w, art, ph: fr(idc * 5.7) * 6.28, id: idc });
    idc++;
    const branch = fr(idc * 3.3) < 0.55 && dep > 1;
    const na = ang + da + (fr(idc * 7.1) - 0.5) * 0.25;
    grow(nx, ny, na, w * 0.82, dep + 1, art, arc * 0.9);
    if (branch) grow(nx, ny, ang - Math.sign(da || 1) * (0.4 + fr(idc * 2.7) * 0.5), w * 0.6, dep + 2, art, arc * 0.5);
  }
  for (const t of trunks) grow(disc.x, disc.y, t.a, u * 0.012, 0, t.art, t.arc);
  S.tree = segs;
}

// ---- draw (composite into a buffer so layer alpha works) ----
const heart = 0.5 + 0.5 * Math.sin(K.t * 1.5 + 0.3) + A.bass * 0.35;
if (!S.fb || S.fw !== width || S.fh !== height) { S.fb = createGraphics(width, height); S.fb.pixelDensity(1); S.fw = width; S.fh = height; }
const f = S.fb;
f.push(); f.colorMode(HSB, 360, 100, 100, 100); f.clear();
f.image(S.base, 0, 0, width, height);

// drifting illumination pool (broad area element -> carries the motion floor)
if (style !== 'schematic') {
  const px2 = cx + Math.cos(K.t * 0.23 * (0.5 + P.drift)) * R * 0.5 + Math.sin(K.t * 0.41) * R * 0.18;
  const py2 = cy + Math.sin(K.t * 0.19 * (0.5 + P.drift) + 1.1) * R * 0.5;
  f.push(); f.blendMode(ADD); f.noStroke();
  for (let k = 4; k >= 1; k--) { const rr = R * (0.35 + k * 0.18); f.fill(style === 'fa' ? 150 : 40, style === 'fa' ? 20 : 30, 100, (2.4 + P.energy * 3.5)); f.ellipse(px2, py2, rr * 2, rr * 2); }
  f.pop();
}

// vessels (clipped to the fundus aperture)
f.push();
f.drawingContext.save();
f.drawingContext.beginPath();
f.drawingContext.arc(cx, cy, R * 0.995, 0, 6.283);
f.drawingContext.clip();
f.noFill(); f.strokeCap(ROUND);
const dens = 0.35 + P.density * 0.65;
const nseg = Math.floor(S.tree.length * dens);
for (let s = 0; s < nseg; s++) {
  const v = S.tree[s];
  const wave = 0.5 + 0.5 * Math.sin(v.ph + K.t * 1.5 - v.id * 0.15);   // pulse travels the tree
  const pw = v.w * (0.82 + 0.28 * (heart * 0.6 + wave * 0.4) * (0.4 + P.pulse));
  let cc;
  if (style === 'fa') cc = [55, 8, 55 + wave * 45 + (v.art ? 15 : 0)];       // bright fluorescent
  else if (style === 'redfree') cc = [130, 60, v.art ? 22 : 12];             // dark vessels on green
  else if (style === 'schematic') cc = [v.art ? 8 : 205, 70, 55 + wave * 30];
  else cc = v.art ? [8, 78, 48 + wave * 22 + heart * 10] : [355, 62, 30 + wave * 14];  // photo
  f.stroke(cc[0], cc[1], cc[2]); f.strokeWeight(pw);
  f.beginShape(); f.vertex(v.x, v.y); f.bezierVertex(v.mx, v.my, v.mx, v.my, v.nx, v.ny); f.endShape();
  if (v.art && style === 'photo' && v.w > u * 0.004) {   // arterial light reflex
    f.stroke(20, 30, 92, 45); f.strokeWeight(pw * 0.3);
    f.beginShape(); f.vertex(v.x, v.y); f.bezierVertex(v.mx, v.my, v.mx, v.my, v.nx, v.ny); f.endShape();
  }
}
f.drawingContext.restore();
f.pop();

// grain
if (P.grain > 0.02 && style !== 'schematic') {
  f.push(); f.blendMode(style === 'fa' ? ADD : MULTIPLY); f.noStroke();
  const gp = 60; for (let k = 0; k < gp * dens; k++) { const gx = fr(k * 1.1 + (K.t * 0.3 | 0)) * width, gy = fr(k * 2.7 + (K.t * 0.3 | 0) + 9) * height; f.fill(0, 0, style === 'fa' ? 100 : 0, P.grain * 12); f.ellipse(gx, gy, u * 0.006, u * 0.006); }
  f.pop();
}
f.pop();

const mag = Math.max(1, P.scale);
const sw = width / mag, sh = height / mag;
const sx = (width - sw) * Math.min(1, Math.max(0, P.x)), sy = (height - sh) * Math.min(1, Math.max(0, P.y));
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(f, 0, 0, width, height, sx, sy, sw, sh);
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
